<?php require 'includes/db.php';require 'includes/helpers.php';require_login();ensure_default_categories($pdo);$month=$_GET['month']??date('Y-m');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$month=$_POST['month'];$amount=(float)$_POST['amount'];$q=$pdo->prepare("INSERT INTO budgets(user_id,month,amount) VALUES(?,?,?) ON CONFLICT(user_id,month) DO UPDATE SET amount=excluded.amount");$q->execute([user_id(),$month,$amount]);$msg='Budget saved.';}$s=stats($pdo,$month);$bud=budget($pdo,$month);$pct=$bud?min(100,$s['month_expense']/$bud*100):0;?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Budget</title><link rel="stylesheet" href="assets/style.css"></head><body class="<?=!empty($_SESSION['dark'])?'dark':''?>"><div class="app"><aside class="sidebar"><?php include 'includes/nav.php';?></aside><main class="main"><header class="top"><div><h1>Monthly Budget</h1><p>Set a spending limit for any month</p></div></header><div class="panel" style="max-width:700px"><?php if($msg):?><div class="alert"><?=$msg?></div><?php endif;?><form method="post" class="budget-form"><input type="month" name="month" value="<?=h($month)?>"><input type="number" step=".01" min="0" name="amount" value="<?=h($bud)?>" placeholder="Budget amount" required><button class="btn primary">Save Budget</button></form><hr style="border:0;border-top:1px solid #edf0f4;margin:25px 0"><h2><?=date('F Y',strtotime($month.'-01'))?></h2><div class="budget-meta"><span>Spent: ₹<?=money($s['month_expense'])?></span><span>Budget: ₹<?=money($bud)?></span></div><div class="progress"><span style="width:<?=$pct?>%"></span></div><p class="muted"><?=money(max(0,$bud-$s['month_expense']))?> remaining</p></div></main></div></body></html>